/**
 * Legacy kill-switch worker.
 *
 * The app's real service worker is `/app-sw.js` (generated by vite-plugin-pwa).
 * This file only exists to evict registrations from older releases that were
 * served at `/sw.js`. It unregisters itself and does nothing else — it must NOT
 * delete caches (that would wipe the current worker's caches) and must NOT
 * force-navigate clients (that could interrupt someone mid-edit).
 */
self.addEventListener("install", () => self.skipWaiting());

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      try {
        await self.clients.claim();
      } finally {
        await self.registration.unregister();
      }
    })(),
  );
});
